#include <stdio.h>
#include <string.h>

#define MAXV 8
#define MAXE 20
#define INF 0x3f3f3f3f

typedef struct { int u, v, w; } Edge;
Edge es[MAXE];
int dist[MAXV];

void bellman(int V, int E, int s) {
    for (int i = 0; i < V; i++) dist[i] = INF;
    dist[s] = 0;

    for (int r = 1; r <= V - 1; r++) {
        int changed = 0;
        for (int i = 0; i < E; i++) {
            int u = es[i].u, v = es[i].v, w = es[i].w;
            if (dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                changed = 1;
            }
        }
        printf("  第 %d 轮松弛后：", r);
        for (int i = 0; i < V; i++) printf("%d:%d ", i, dist[i]);
        printf("\n");
        if (!changed) { printf("  （已收敛，提前结束）\n"); break; }
    }

    /* 第 V 轮仍能松弛 => 存在从 s 可达的负环 */
    int neg = 0;
    for (int i = 0; i < E; i++) {
        int u = es[i].u, v = es[i].v, w = es[i].w;
        if (dist[u] != INF && dist[u] + w < dist[v]) { neg = 1; break; }
    }
    printf("  负环检测：%s\n", neg ? "存在负环，最短路无解（可无限松弛）" : "无负环，结果有效");
}

int main(void) {
    /* 情形一：有负权边但无负环 */
    printf("=== 情形一：含负权边，但无负环 ===\n");
    int e1[][3] = {{0,1,1},{1,2,-3},{2,3,2},{0,3,5}};
    int m1 = 4;
    for (int i = 0; i < m1; i++) { es[i].u = e1[i][0]; es[i].v = e1[i][1]; es[i].w = e1[i][2]; }
    bellman(4, m1, 0);

    printf("\n  手工验算：d[1]=1, d[2]=1+(-3)=-2, d[3]=min(5, -2+2=0)=0\n\n");

    /* 情形二：含负环 1->2->1，权和 -2 */
    printf("=== 情形二：含负环 1->2->1（权和 = -3+1 = -2） ===\n");
    int e2[][3] = {{0,1,1},{1,2,-3},{2,1,1},{2,3,2}};
    int m2 = 4;
    for (int i = 0; i < m2; i++) { es[i].u = e2[i][0]; es[i].v = e2[i][1]; es[i].w = e2[i][2]; }
    bellman(4, m2, 0);

    printf("\n要点：V-1 轮足够（无负环时最短路最多 V-1 条边）；第 V 轮仍能松弛即证明有负环。\n");
    return 0;
}
